using Microsoft.EntityFrameworkCore; using OpenFlux.Zen.Server.Models; namespace OpenFlux.Zen.Server.Data; public sealed class AppDbContext(DbContextOptions<AppDbContext> options):DbContext(options){ public DbSet<Tunnel> Tunnels=>Set<Tunnel>(); public DbSet<AppSettings> Settings=>Set<AppSettings>(); protected override void OnModelCreating(ModelBuilder b){b.Entity<AppSettings>().HasKey(x=>x.Id);b.Entity<Tunnel>().HasIndex(x=>x.Name).IsUnique();}}
